//! Code generated by `protoc` often holds the whole file description, as the
//! bytes of a `FileDescriptorProto`: that is the exact original, whatever the
//! language. Each generator writes it its own way.

use base64::Engine as _;
use prost::Message as _;
use prost_types::{FileDescriptorProto, FileDescriptorSet};
use regex::Regex;

/// The bytes of a string literal starting at `start` (its opening quote),
/// and where it ends. The escapes are the ones Python, Java, Go, Ruby, PHP
/// and C share.
fn string_literal(text: &str, start: usize) -> Option<(Vec<u8>, usize)> {
    let bytes = text.as_bytes();
    let quote = *bytes.get(start)?;
    let mut out = Vec::new();
    let mut ix = start + 1;
    while ix < bytes.len() {
        let c = bytes[ix];
        if c == quote {
            return Some((out, ix + 1));
        }
        if c != b'\\' {
            out.push(c);
            ix += 1;
            continue;
        }
        let next = *bytes.get(ix + 1)?;
        ix += 2;
        match next {
            b'n' => out.push(b'\n'),
            b't' => out.push(b'\t'),
            b'r' => out.push(b'\r'),
            b'a' => out.push(7),
            b'b' => out.push(8),
            b'v' => out.push(11),
            b'f' => out.push(12),
            b'e' => out.push(27),
            b'\n' => {}
            b'x' => {
                let hex = text.get(ix..ix + 2)?;
                out.push(u8::from_str_radix(hex, 16).ok()?);
                ix += 2;
            }
            b'u' => {
                let hex = text.get(ix..ix + 4)?;
                let unit = u32::from_str_radix(hex, 16).ok()?;
                ix += 4;
                if unit < 0x80 {
                    out.push(unit as u8);
                } else {
                    let c = char::from_u32(unit)?;
                    out.extend_from_slice(c.encode_utf8(&mut [0; 4]).as_bytes());
                }
            }
            b'0'..=b'7' => {
                let mut value = u32::from(next - b'0');
                let mut count = 1;
                while count < 3 && matches!(bytes.get(ix), Some(b'0'..=b'7')) {
                    value = value * 8 + u32::from(bytes[ix] - b'0');
                    ix += 1;
                    count += 1;
                }
                out.push(value as u8);
            }
            other => out.push(other),
        }
    }
    None
}

/// Adjacent string literals as one, however they are joined (`+`, `,`,
/// nothing, Go's `"" +`). Comments between them are not expected.
fn joined_literals(text: &str, mut ix: usize) -> Vec<u8> {
    let mut out = Vec::new();
    loop {
        while text[ix..].starts_with(|c: char| c.is_whitespace() || c == '+' || c == ',') {
            ix += 1;
        }
        // A Kotlin or C `@`/`L` prefix is not used for these; plain quotes only.
        if !text[ix..].starts_with('"') {
            return out;
        }
        match string_literal(text, ix) {
            Some((bytes, end)) => {
                out.extend(bytes);
                ix = end;
            }
            None => return out,
        }
    }
}

fn hex_list(text: &str) -> Vec<u8> {
    text.split(',')
        .filter_map(|item| {
            let item = item.trim();
            let hex = item
                .strip_prefix("0x")
                .or_else(|| item.strip_prefix("0X"))?;
            u8::from_str_radix(hex, 16).ok()
        })
        .collect()
}

fn from_hex(text: &[u8]) -> Option<Vec<u8>> {
    let text = std::str::from_utf8(text).ok()?;
    if text.len() % 2 != 0 {
        return None;
    }
    (0..text.len())
        .step_by(2)
        .map(|ix| u8::from_str_radix(text.get(ix..ix + 2)?, 16).ok())
        .collect()
}

fn base64_of(text: &[u8]) -> Option<Vec<u8>> {
    let engine = base64::engine::general_purpose::STANDARD_NO_PAD;
    let text: Vec<u8> = text.iter().copied().filter(|c| *c != b'=').collect();
    engine.decode(text).ok()
}

/// What each generator's output holds, as bytes that may be a description.
fn candidates(text: &str) -> Vec<Vec<u8>> {
    let mut found = Vec::new();
    let pattern = |p: &str| Regex::new(p).expect("a valid pattern");

    // Python: AddSerializedFile(b'…'), older ones serialized_pb=b'…'.
    for m in
        pattern(r#"(?:AddSerializedFile\(\s*|serialized_pb\s*=\s*(?:_b\()?)b?['"]"#).find_iter(text)
    {
        if let Some((bytes, _)) = string_literal(text, m.end() - 1) {
            found.push(bytes);
        }
    }
    // Java and Kotlin: String[] descriptorData = { "…" + "…", "…" };
    for m in pattern(r"descriptorData\s*=\s*\{").find_iter(text) {
        found.push(joined_literals(text, m.end()));
    }
    // C#: Convert.FromBase64String(string.Concat("…", "…"))
    for m in pattern(r"FromBase64String\(\s*(?:string\.Concat\(\s*)?").find_iter(text) {
        found.extend(base64_of(&joined_literals(text, m.end())));
    }
    // Go: file_x_rawDesc = []byte{0x0a, …}, or a string since 2025.
    for m in pattern(r"_rawDesc\s*=\s*(?:string\()?\[\]byte\{").find_iter(text) {
        let rest = &text[m.end()..];
        let end = rest.find('}').unwrap_or(rest.len());
        found.push(hex_list(&rest[..end]));
    }
    for m in pattern(r"_rawDesc\s*=\s*").find_iter(text) {
        found.push(joined_literals(text, m.end()));
    }
    // Ruby: descriptor_data = "…"
    for m in pattern(r"descriptor_data\s*=\s*").find_iter(text) {
        found.push(joined_literals(text, m.end()));
    }
    found.extend(php_candidates(text.as_bytes()));
    // C++: descriptor_table_protodef_x[] … = { "…" "…" };
    for m in pattern(r"descriptor_table_protodef_\w+\[\][^=]*=\s*\{?").find_iter(text) {
        found.push(joined_literals(text, m.end()));
    }
    // TypeScript and JavaScript from protobuf-es: fileDesc("…")
    for m in pattern(r"\bfileDesc\(\s*").find_iter(text) {
        if text[m.end()..].starts_with('"') {
            found.extend(base64_of(&joined_literals(text, m.end())));
        }
    }
    found
}

/// PHP: `internalAddGeneratedFile('…', true)` with the raw bytes in a
/// single-quoted string, or `hex2bin("…")`. The raw bytes are why a PHP file
/// need not be text at all.
fn php_candidates(source: &[u8]) -> Vec<Vec<u8>> {
    let call = regex::bytes::Regex::new(r"internalAddGeneratedFile\(\s*(hex2bin\(\s*)?(['\x22])")
        .expect("a valid pattern");
    let mut found = Vec::new();
    for c in call.captures_iter(source) {
        let quote = c[2][0];
        let mut ix = c.get(0).expect("the whole match").end();
        let mut out = Vec::new();
        while let Some(&b) = source.get(ix) {
            if b == quote {
                break;
            }
            if b == b'\\'
                && matches!(source.get(ix + 1), Some(&next) if next == quote || next == b'\\')
            {
                out.push(source[ix + 1]);
                ix += 2;
                continue;
            }
            out.push(b);
            ix += 1;
        }
        if c.get(1).is_some() {
            found.extend(from_hex(&out));
        } else {
            found.push(out);
        }
    }
    found
}

/// The file descriptions in a file that is not text: PHP's metadata.
pub(super) fn extract_bytes(source: &[u8]) -> Vec<FileDescriptorProto> {
    decoded(php_candidates(source))
}

/// The file descriptions held in generated code, if it holds any.
pub(super) fn extract(text: &str) -> Vec<FileDescriptorProto> {
    decoded(candidates(text))
}

fn decoded(candidates: Vec<Vec<u8>>) -> Vec<FileDescriptorProto> {
    let mut files: Vec<FileDescriptorProto> = Vec::new();
    for bytes in candidates {
        // PHP's metadata is a whole set, the others one file.
        let found = match FileDescriptorProto::decode(bytes.as_slice()) {
            Ok(file) => vec![file],
            Err(_) => FileDescriptorSet::decode(bytes.as_slice())
                .map(|set| set.file)
                .unwrap_or_default(),
        };
        for file in found {
            if file.name().ends_with(".proto") && !files.iter().any(|f| f.name() == file.name()) {
                files.push(file);
            }
        }
    }
    files
}
